(async()=>{
const g=__game; const wait=(ms)=>new Promise(r=>setTimeout(r,ms));
const until=async(f,ms=30000)=>{const t=performance.now(); while(!f()){ if(performance.now()-t>ms) return false; await wait(100);} return true;};
if(!window.__bot) __autoplay(); __bot.paused=true;
g.scene.getScenes(true).filter(s=>s.scene.key!=='Notify').forEach(s=>s.scene.stop());
__setFoliage(false); __gearFor(1,1,3); const run=__run.start({heroId:'rowan',seed:9}); run.mutator=undefined; run.depth=1; run.floor=3; run.level=30;
for(let i=0;i<6;i++){ const o=__run.boonOffers(run,3)[0]; if(o) __run.addBoon(run,o.def.id); }
g.scene.start('RunMap'); await until(()=>g.scene.isActive('RunMap')); await wait(600);
const m=g.scene.getScene('RunMap'); const c=__run.choices(run); const node=c[0]; node.kind='challenge'; m.select(node);
await until(()=>g.scene.isActive('Room') && g.scene.getScene('Room').player);
const r=g.scene.getScene('Room'); window.__inv=setInterval(()=>{ if(r.player){ r.player.invuln=5; r.player.hp=r.player.maxHp; } },100);
const times=[]; const orig=g.loop.callback; g.loop.callback=function(a,b){ const t0=performance.now(); orig(a,b); times.push(performance.now()-t0); };
window.__times=times; __bot.paused=false; return 'started';
})()

